const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=n=>(n>0?'+':'')+Number(n).toLocaleString('ko-KR');
export function renderMonthlyRanking(section,data,{viewerId='',error='',loading=false}={}){
 const rows=data?.entries||[],me=data?.personal;
 section.innerHTML=`<div class="rummi-monthly-heading"><h2>월간 랭킹 TOP 30</h2><span>매월 1일 0시 초기화</span></div><p class="rummi-rank-rule">1위 횟수 → 승률 → 누적 공식 점수 · 모두 같으면 공동 순위</p>${rows.length?`<div class="rummi-rank-table" role="table" aria-label="회원 월간 랭킹"><div class="rummi-rank-head" role="row"><span role="columnheader">순위</span><span role="columnheader">이름</span><span role="columnheader">1위</span><span role="columnheader">승률</span><span role="columnheader">참가</span></div>${rows.map(row=>`<div class="rummi-rank-row" role="row" data-me="${row.userId===viewerId}"><span class="rummi-rank-place" role="cell" data-rank="${row.rank}">${row.rank}</span><div class="rummi-rank-person" role="cell"><strong title="${esc(row.name)}">${esc(row.name)}</strong><small>꼴찌 ${row.lasts}회 · ${signed(row.score)}점</small></div><span role="cell">${row.wins}회</span><strong role="cell">${Number(row.winRate).toLocaleString('ko-KR',{maximumFractionDigits:1})}%</strong><span role="cell">${row.games}회</span></div>`).join('')}</div>`:`<p class="rummi-rank-empty">${loading?'랭킹을 불러오는 중입니다.':error?'랭킹을 불러오지 못했습니다.':'이번 달 완료된 경기가 없습니다.'}</p>`}${me?`<p class="rummi-personal-ranking">내 순위 <strong>${me.rank}위</strong><span>1위 ${me.wins}회 / ${me.games}경기 · 승률 ${Number(me.winRate).toLocaleString('ko-KR',{maximumFractionDigits:1})}%</span></p>`:!loading&&!error?'<p class="rummi-personal-ranking">이번 달 첫 경기를 완료하면 랭킹에 반영됩니다.</p>':''}${error?`<p class="rummi-ranking-error" role="status">${esc(error)}</p>`:''}`;
}
